def best_profit(prices):
    low, best = prices[0] if prices else 0, 0
    for price in prices:
        low, best = min(low, price), max(best, price - low)
    return best

def window_sums(values, k):
    totals = [sum(values[:k])]
    for end in range(k, len(values)):
        totals.append(totals[-1] - values[end - k] + values[end])
    return totals

def labels(number):
    result = []
    if number > 0: result.append('positive')
    if number % 2 == 0: result.append('even')
    return result
